 s2:{place:'exterior',season:'늦가을',age:'열 살',chLabel:CHLAB,chars:[{id:'marot',pos:'center'}],
  paras:[
   '트로네 공작 저택은 생각보다 조용했다. 큰 저택이란 응당 시끄러울 줄 알았다. 그런데 이곳은 모든 것이 제자리에 있어서 소리조차 정돈된 느낌이었다.',
   '현관 계단 아래에는 마중 나온 사람이 한 명뿐이었다. 검은 옷을 입은 젊은 남자였고, 서른 남짓으로 보였다. 단추 하나, 주름 하나 어긋남 없이 서 있어서, 마차보다 먼저 거기에 있었던 사람 같았다.',
   '"마로트라고 합니다. 이 저택의 집사를 맡고 있습니다. 먼 길 오시느라 고생 많으셨습니다, 아델라인 아가씨."',
   '그는 정확한 각도로 고개를 숙였다. 나는 그가 {{bow|내 눈높이에 맞추어 허리를 굽혔다}}는 것을 알아챘다. 어른이 아이에게 하는 방식이 아니라, 손님에게 하는 방식으로.'
  ],
  choices:[{label:'"공작님은……" 하고 묻는다',next:'s3',flag:'askedDuke'},{label:'아무것도 묻지 않고 계단을 올려다본다',next:'s3'}]},
