   '냄비 뚜껑이 부딪치는 소리, 반죽을 내리치는 소리, 누군가 큰 소리로 웃다가 더 큰 목소리에 혼나는 소리. 복도를 지나는 동안 조용하던 집이 이 문 하나 안에서는 갑자기 살아 있었다.',
