 // ── 2권 10장 〈북쪽에서 온 소년〉 (사용자 승인 설계: 편들기(lateLaugh 필요) / 떠나는 카일런에게 / 서명 없는 노트 해석)
 c10a:{place:'hall',season:'늦여름',age:'열 살',chLabel:'2권 · 10장 북쪽에서 온 소년',chars:[{id:'marot',pos:'right'}],
  paras:[
   '북부 손님들은 이레를 머물렀다.',
   '첫날부터 저택의 규칙이 조금씩 어긋났다. 새벽 네 시에 마구간에서 낯선 소리가 났고, 나는 그것이 북부 소년이 자기 말을 직접 돌보는 소리라는 것을 알았다. 마로트는 그것을 알면서도 말리지 않았다. {{dawn|두 사람의 새벽 순찰이 마구간 앞에서 마주쳤다는 이야기}}를 탠지가 눈을 반짝이며 전했을 때, 나는 노트에 한 줄을 적었다.',
   {t:'*—마로트 님과 북부 소년은 비슷한 시간에 일어난다. 둘 다 그 얘기를 하지 않는다.*',ifN:'dawn'},
   '오후마다 서재의 문이 닫혔다. 문 너머의 목소리는 낮고 길었고, 이따금 끊겼다. {{lowvoice|북부 대공은 소리를 낮추는 법을 모르는 사람처럼 보였는데, 그 방에서만은 낮추고 있었다.}}'
  ],
  choices:[{label:'사흘째 오후, 과수원으로',next:'c10b'}]},
 c10b:{place:'orchard',season:'늦여름',age:'열 살',chLabel:'2권 · 10장 북쪽에서 온 소년',chars:[{id:'kylen',pos:'left'},{id:'adrian',pos:'right'}],
  paras:[
   '사흘째 오후, 과수원으로 가는 길에 카일런을 만났다.',
   '그는 사과나무 아래에 서서 가지를 올려다보고 있었다. 손은 뒤로 모으고 턱은 조금 들고, 나무가 자기 앞에서 변명해야 한다는 듯한 자세였다.',
   '"북부에는 이런 나무가 없다."',
   '인사도 없이 그가 말했다.',
   '"사과가 안 열리나요?"',
   '"열린다. 하지만 가지가 이렇게 부드럽지 않다. 겨울을 견디려면 단단해야 하니까. 이건 겨울을 한 번도 걱정해 본 적 없는 나무 같군."',
   '칭찬인지 비난인지, 아마 그 자신도 몰랐을 것이다. 나는 대답하지 않았다.',
   '"겨울 걱정 없는 나무한테 겨울 걱정을 시키는 건 좀 가혹하지 않아?"',
   '담 위에서 목소리가 내려왔다. 아드리안이 책을 무릎에 올린 채 앉아 있었다. 카일런이 고개를 돌렸다.',
   '"……누구냐."',
   '"담 너머에 사는 아드리안 웨스트콧. 둘째 아들. 한가한 쪽이야."',
   '"한가한 둘째 아들이라면 이 근방에서 책이나 읽고 있겠군."',
   '그 말투에는 악의가 없었다. 그래서 더 날카로웠다. {{latelaugh|아드리안은 웃었지만 그 웃음이 평소보다 반 박자 늦었다.}}'
  ],
  choices:[{label:'"한가한 게 아니에요."',next:'c10c',flag:'defended',req:'latelaugh'},{label:'보고만 있는다',next:'c10c',flag:'justWatched'}]},
 c10c:{place:'orchard',season:'늦여름',age:'열 살',chLabel:'2권 · 10장 북쪽에서 온 소년',chars:[{id:'kylen',pos:'left'},{id:'adrian',pos:'right'}],
  paras:[
   {t:'나는 그것을 보았고, 그리고 처음으로 보고만 있지 않았다.',if:'defended'},
   {t:'"한가한 게 아니에요."',if:'defended'},
   {t:'두 사람이 동시에 나를 보았다. 내 목소리가 내가 생각한 것보다 또렷하게 나왔다.',if:'defended'},
   {t:'"읽고 있는 거예요. 세르반 산맥 측량 보고서요."',if:'defended'},
   {t:'나는 보고만 있었다. 아드리안은 대수롭지 않다는 듯 두꺼운 책을 들어 보였다. "한가하니까 이런 걸 읽지. 세르반 산맥 측량 보고서."',if:'justWatched'},
   '"……세르반?"',
   '카일런의 눈빛이 변했다. 아드리안이 두꺼운 책을 들어 보였다.',
   '"형 서재에서 빌렸어. 제국 측량국 판본이야."',
   '카일런은 한참 말이 없다가, 마침내 담 쪽으로 걸어왔다. 그는 책을 받아 한 장을 넘기고, 곧 눈살을 찌푸렸다.',
   '"능선이 틀렸다."',
   '"어디가?"',
   '"여기. 이 고개는 여름에만 열린다. 보고서는 항상 열린 것처럼 그려져 있지만, 겨울에는 눈이 허리까지 쌓여서 길이 아니라 벽이다. 측량관들은 여름에만 왔으니 몰랐겠지."',
   '그는 땅에서 나뭇가지를 주워 흙 위에 선을 그었다. 능선, 고개, 얼어붙는 강. 아드리안은 담에서 내려와 책 여백에 그 선을 그대로 따라 그렸다. 두 소년은 머리를 맞대고 한 시간 가까이 땅바닥의 산맥을 고쳤다. 나는 그 곁에 서서 그들을 보았다. 그날 오후 카일런은 처음으로 나이 든 사람처럼 말하지 않고, 열두 살처럼 말했다.',
   '그러다 알아챘다. {{lefthand|그가 나뭇가지를 쥔 손은 왼손이었다.}} 세밀한 선을 그을 때도 오른손은 장갑 속에 숨긴 채 허벅지 옆에 붙어 있었다.',
   {t:'"또 장갑이냐."',if:'askedGlove'},
   {t:'"장갑을 보는군."',not:'askedGlove'},
   '카일런이 고개를 들지도 않고 말했다.',
   '"……아니에요."',
   '"거짓말이군."',
   '"……조금요."',
   '그는 나뭇가지를 내려놓았다. 일어서서 무릎의 흙을 털고, 나를 보았다. 얼음 조각 같은 눈 속에 짧게 무언가가 스쳤다. 화는 아니었다. 화보다 훨씬 서툰 것이었다.',
   '"나는 정직한 사람은 좋아한다. 하지만 침묵으로 정직한 척하는 사람은 모르겠다."',
   '그는 돌아서서 걸어갔다. 아드리안이 땅의 산맥을 내려다보다가 낮게 말했다.',
   '"저거, 칭찬은 아니었지?"',
   '"아마도요."',
   {t:'"그래도 너, 오늘 처음으로 누구 편을 들었어."',if:'defended'},
   {t:'"너 오늘도 아무 말 안 했네. 근데 다 보고 있었지?"',if:'justWatched'},
   '나는 그 말에 대답하지 못했다. 맞는 말이라서.'
  ],
  choices:[{label:'북부 손님들이 떠나는 날',next:'c10d'}]},
