   {t:'그 뒤로 우리는 점심마다 공부방 책상의 지도를 걷고 접시를 놓았다. 마르타 아주머니는 처음 이틀은 쟁반만 보내더니, 사흘째에는 호두 과자를 두 개씩 더 올려 보냈다. 선생은 아무 말도 하지 않고 두 개 모두 먹었다.',if:'schoolLunch'}
