  "한 가지 부탁이 있습니다. 선생께서 허락하신다면, 저는 이 편지들을 아가씨께 드리고 싶습니다. 부치지 못한 편지이니 읽을 사람이 정해져 있지 않습니다. 하지만 읽을 사람이 필요하다면, 그 아이만 한 독자는 없을 것입니다.",
